void gen_facts() {
    base cur = 1;
    for(int i = 0; i < mod; i++) {
        if(i % step == 0) {
            cout << cur << ",";
        }
        cur *= i + 1;
    }
}

base prefact(int n) {
    base cur = facts[n / step];
    for(int i = n - n % step; i < n; i++) {
        cur *= i + 1;
    }
    return cur;
}

void solve() {
    int n;
    cin >> n;
    cout << prefact(n) << "\n";
}

signed main() {
    //freopen("input.txt", "r", stdin);
    ios::sync_with_stdio(0);
    cin.tie(0);
    int t = 1;
    cin >> t;
    while(t--) {
        solve();
    }
}
